        bool light=theme.SelectedIndex==1;Palette.Background=light?Color.FromArgb(236,239,241):Color.FromArgb(13,20,26);Palette.Card=light?Color.FromArgb(252,252,250):Color.FromArgb(23,32,40);Palette.Field=light?Color.FromArgb(245,247,246):Color.FromArgb(16,24,31);Palette.Border=light?Color.FromArgb(178,189,194):Color.FromArgb(49,64,77);Palette.Text=light?Color.FromArgb(32,41,48):Color.FromArgb(234,238,249);Palette.Muted=light?Color.FromArgb(88,104,116):Color.FromArgb(157,173,193);Palette.Gold=designAccent=="Turquoise"?Color.FromArgb(20,211,204):designAccent=="Purple"?Color.FromArgb(151,121,237):designAccent=="Blue"?Color.FromArgb(70,158,248):Color.FromArgb(232,190,104);
        ThemeTree(this);foreach(var line in rules)line.BackColor=Palette.Border;brandMark.Ink=Palette.Gold;brand.ForeColor=Palette.Gold;brandSub.ForeColor=Palette.Muted;versionBadge.ForeColor=Palette.Muted;clientBadge.ForeColor=Palette.Gold;clientBadge.BackColor=light?Color.FromArgb(252,241,212):Color.FromArgb(49,39,19);stateIcon.Ink=Palette.Gold;settingsIcon.Ink=appearanceIcon.Ink=applicationIcon.Ink=folderIcon.Ink=Palette.Gold;noticeIcon.Ink=Palette.Gold;
        foreach(var label in new Label[]{filePath,fileHint,stateDescription,settingsSub,logFolderSub,logFolderPath,updateHint,logsSub,privacy,logCount,previewPlaceholder,footer,searchHint})label.ForeColor=Palette.Muted;
        status.ForeColor=Palette.Gold;for(int i=0;i<swatches.Length;i++){swatches[i].Active=designAccent==new string[]{"Gold","Turquoise","Purple","Blue"}[i];swatches[i].Invalidate();}
        logGrid.BackgroundColor=Palette.Field;logGrid.GridColor=Palette.Border;logGrid.ColumnHeadersDefaultCellStyle.BackColor=Palette.Card;logGrid.ColumnHeadersDefaultCellStyle.ForeColor=Palette.Muted;logGrid.DefaultCellStyle.BackColor=Palette.Field;logGrid.DefaultCellStyle.ForeColor=Palette.Text;logGrid.DefaultCellStyle.SelectionBackColor=Palette.Tint(Palette.Card,Palette.Gold,.06f);logGrid.DefaultCellStyle.SelectionForeColor=Palette.Text;
        Invalidate(true);
    }
    void ThemeTree(Control root){root.ForeColor=Palette.Text;if(root==this||root==header||root==tabs||Array.IndexOf(pages,root)>=0)root.BackColor=Palette.Background;else if(root is PremiumCard)root.BackColor=Palette.Card;else if(root is TextBox||root is ComboBox)root.BackColor=Palette.Field;foreach(Control child in root.Controls)ThemeTree(child);}
    void AppendLogEntries(string text){if(String.IsNullOrEmpty(text))return;logBook.Add(text);logDirty=true;if(!viewPaused&&selectedPage==2)RefreshLogView(false);}
    void SetLogPaused(bool pause){viewPaused=pause;frozenLogs=pause?logBook.Snapshot():null;pauseLogs.Text=pause?"Görünümü Sürdür":"Görünümü Duraklat";pauseLogs.Symbol=pause?"play":"pause";logDirty=true;RefreshLogView(true);}
    void RefreshLogView(bool force){if(logGrid==null||logGrid.IsDisposed||(!force&&selectedPage!=2))return;if(!force&&(viewPaused||(!logDirty&&renderedRevision==logBook.Revision)))return;visibleLogs=LogBook.Filter(viewPaused?frozenLogs:logBook.Snapshot(),search.Text,levelFilter.SelectedIndex<=0?"":levelFilter.SelectedItem.ToString());logGrid.RowCount=visibleLogs.Count;for(int i=0;i<logGrid.Rows.Count;i++)logGrid.Rows[i].Height=(int)((visibleLogs[i].Id==expandedLog?115:52)*layoutScale);if(autoScroll.Checked&&visibleLogs.Count>0)logGrid.FirstDisplayedScrollingRowIndex=visibleLogs.Count-1;logCount.Text=visibleLogs.Count+" kayıt gösteriliyor"+(viewPaused?" · Duraklatıldı":"");renderedRevision=logBook.Revision;logDirty=false;logGrid.Invalidate();}
    void PaintLogCell(object sender,DataGridViewCellPaintingEventArgs e){if(e.RowIndex<0||e.RowIndex>=visibleLogs.Count)return;var row=visibleLogs[e.RowIndex];if(e.ColumnIndex==1){e.PaintBackground(e.ClipBounds,true);Color color=row.Level=="UYARI"?Palette.Gold:row.Level=="HATA"?Palette.Red:Palette.Turquoise;var rect=new Rectangle(e.CellBounds.X+(int)(28*layoutScale),e.CellBounds.Y+(int)(10*layoutScale),(int)(76*layoutScale),(int)(31*layoutScale));e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=RoundedPanel.Shape(rect,(int)(7*layoutScale)))using(var brush=new SolidBrush(Palette.Tint(Palette.Field,color,.12f)))using(var pen=new Pen(Palette.Tint(Palette.Field,color,.7f))){e.Graphics.FillPath(brush,path);e.Graphics.DrawPath(pen,path);}TextRenderer.DrawText(e.Graphics,row.Level,DFont(17,true),rect,color,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);e.Paint(e.ClipBounds,DataGridViewPaintParts.Border);e.Handled=true;}else if(e.ColumnIndex==2&&row.Id==expandedLog){e.PaintBackground(e.ClipBounds,true);var rect=e.CellBounds;rect.Inflate(-(int)(28*layoutScale),-(int)(8*layoutScale));TextRenderer.DrawText(e.Graphics,row.Message,logGrid.DefaultCellStyle.Font,new Rectangle(rect.X,rect.Y,rect.Width,(int)(34*layoutScale)),Palette.Text,TextFormatFlags.EndEllipsis);TextRenderer.DrawText(e.Graphics,"Ayrıntı: "+row.Message,DFont(17,false),new Rectangle(rect.X,rect.Y+(int)(38*layoutScale),rect.Width,rect.Height-(int)(38*layoutScale)),Palette.Muted,TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis);e.Paint(e.ClipBounds,DataGridViewPaintParts.Border);e.Handled=true;}}
    void ShowProxyList(){using(var dialog=new Form{Text="NiyaziSUGAR · Proxy Listesi",ClientSize=new Size(600,430),StartPosition=FormStartPosition.CenterParent,BackColor=Palette.Background,ForeColor=Palette.Text}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Palette.Field,ForeColor=Palette.Text,Font=new Font("Segoe UI",12),BorderStyle=BorderStyle.None};foreach(var item in proxies.Items)list.Items.Add(item);if(proxies.SelectedIndex>=0)list.SelectedIndex=proxies.SelectedIndex;var panel=new Panel{Dock=DockStyle.Bottom,Height=62,BackColor=Palette.Card};var choose=Button(panel,"Seç","check","primary",delegate{if(proxies.Enabled&&list.SelectedIndex>=0){proxies.SelectedIndex=list.SelectedIndex;dialog.Close();}});choose.SetBounds(430,12,150,40);choose.Enabled=proxies.Enabled;list.DoubleClick+=delegate{choose.PerformClick();};dialog.Controls.Add(list);dialog.Controls.Add(panel);dialog.ShowDialog(this);}}
    protected override void Dispose(bool disposing){if(disposing){if(logTimer!=null)logTimer.Dispose();foreach(var font in designFonts.Values)font.Dispose();}base.Dispose(disposing);}
